    "g": Fraction(1, 1000),
    "lb": Fraction(45359237, 100000000),
    "oz": Fraction(28349523125, 1000000000000),
}
PRIORITY = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]
