    return int(re.sub(r"\D", "", text))


def normalize_status(text):
    return re.sub(r"[ \-]+", "_", (text or "").strip().lower())


def counted(status):
    return status in ("delivered", "delivered_late")


def unit_of(text, default):
    if not text:
        return default
    match = re.match(r"\s*([a-zA-Z]+)", text)
    name = match.group(1).lower() if match else ""
    return name if name in FACTORS else default


def parse_decimal(text, style):
    text = text.strip()
    if style == "comma":
        text = text.replace(".", "").replace(",", ".")
    else:
        text = text.replace(",", "")
    return Fraction(Decimal(text))


def split_weight(text, style):
    match = re.match(r"^\s*([-+0-9.,]+)\s*([A-Za-z]+)?\s*$", text)
    if not match:
        return None, None
    unit = match.group(2).lower() if match.group(2) else None
    if unit not in FACTORS:
        unit = None
    return parse_decimal(match.group(1), style), unit


def to_utc_date(year, month, day):
