            moment = moment - sign * offset
        return moment.replace(tzinfo=datetime.timezone.utc)
    match = re.match(r"^(\d{1,2}) ([A-Za-z]{3})[A-Za-z]* (\d{4})$", text)
    if match:
        return to_utc_date(int(match.group(3)), MONTHS[match.group(2).lower()], int(match.group(1)))
    form = (form or "iso").strip().lower()
    if form == "serial" or re.match(r"^\d+(\.\d+)?$", text) and form == "serial":
        base = datetime.datetime(1899, 12, 30, tzinfo=datetime.timezone.utc)
        return base + datetime.timedelta(days=int(float(text)))
    if form == "yyyyddd":
        base = to_utc_date(int(text[:4]), 1, 1)
        return base + datetime.timedelta(days=int(text[4:7]) - 1)
    if form == "yyyymmdd":
        return to_utc_date(int(text[:4]), int(text[4:6]), int(text[6:8]))
    parts = re.split(r"[-/.]", text)
    if form in ("dmy", "dd/mm/yyyy", "dd.mm.yyyy"):
        return to_utc_date(int(parts[2]), int(parts[1]), int(parts[0]))
    if form == "mm/dd/yyyy":
        return to_utc_date(int(parts[2]), int(parts[0]), int(parts[1]))
    return to_utc_date(int(parts[0]), int(parts[1]), int(parts[2]))


def kind_of(raw):
    raw = (raw or "").strip().lower()
    if raw in ("c", "cor", "corr", "correction", "amend"):
        return "correction"
    if raw in ("v", "void"):
        return "void"
    return "new"


def make_record(kind, ident, shipped, kilograms, status):
    return {"kind": kind, "num": number_of(ident), "shipped": shipped, "kg": kilograms, "status": status}


def logical_rows(text):
    lines = text.split("\n")
    index = 0
    while index < len(lines):
        line = lines[index].rstrip("\r")
        index += 1
        if line.startswith("#"):
            yield ("comment", line)
            continue
        if not line.strip():
            continue
        while line.count('"') % 2 == 1 and index < len(lines):
            line += "\n" + lines[index].rstrip("\r")
            index += 1
        yield ("row", line)


def parse_delimited(depot, text):
    delim = DELIMS[depot]
    columns = COLUMNS[depot]
    seq = None
    directives = {}
    header = None
    records = []
    for kind_of_line, line in logical_rows(text):
        if kind_of_line == "comment":
            match = re.match(r"^#\s*seq\s*[:=]\s*(\d+)", line, re.I) or re.match(r"^#\s*\w+ export seq=(\d+)", line)
            if match and seq is None:
                seq = int(match.group(1))
                continue
            match = re.match(r"^#\s*([^:=]+?)\s*:\s*(.*?)\s*$", line)
            if match:
                directives[match.group(1).strip().lower()] = match.group(2)
            continue
        fields = next(csv.reader([line], delimiter=delim, quotechar='"')) if delim == "," else line.split(delim)
        stripped = [field.strip() for field in fields]
        if stripped and all(field in columns for field in stripped if field != "") and \
                sum(1 for field in stripped if field in columns) >= 2 and "TOTAL" not in stripped:
            header = stripped
            continue
        if header is None:
            header = columns
        first = fields[0].strip() if fields else ""
        if first.upper() == "TOTAL" or re.match(r"^\d+ records?$", first):
            continue
        extra = None
        if len(fields) > len(header):
            extra = fields[len(header)]
            fields = fields[:len(header)]
        row = dict(zip(header, fields))
        record = build_delimited(depot, row, extra, directives)
        if record:
            records.append(record)
    return seq, records


def build_delimited(depot, row, extra, directives):
    date_form = directives.get("dates") or directives.get("date format")
    unit_directive = directives.get("unit") or directives.get("weight unit")
    if depot == "east":
        ident, kind, shipped = row.get("id"), kind_of(row.get("type")), row.get("shipped")
        weight, status = row.get("gross"), row.get("status")
        base_form, style, default_unit = "ymd", "dot", "kg"
    elif depot == "harbor":
        ident, kind, shipped = row.get("ref"), kind_of(row.get("rec")), row.get("date")
        weight, status = row.get("weight"), row.get("state")
        base_form, style, default_unit = "iso", "dot", "kg"
    elif depot == "lakeside":
        ident, kind, shipped = row.get("id"), kind_of(row.get("kind")), row.get("shipped")
        weight, status = row.get("gross_kg"), row.get("status")
        base_form, style, default_unit = "iso", "dot", "kg"
    elif depot == "river":
        ident, kind, shipped = row.get("ref"), kind_of(row.get("t")), row.get("shipped")
        weight, status = row.get("weight"), row.get("status")
        base_form, style, default_unit = "mm/dd/yyyy", "dot", "kg"
    else:
        ident, kind, shipped = row.get("id"), kind_of(row.get("typ")), row.get("shipped")
        weight, status = row.get("weight"), row.get("status")
        base_form, style, default_unit = "dd.mm.yyyy", "comma", "kg"
    if not ident or not re.search(r"\d", ident):
        return None
    if kind == "void":
        return make_record("void", ident, None, None, None)
    form = date_form or base_form
    when = parse_time(shipped, form)
    amount, own_unit = split_weight(weight, style)
    unit = own_unit or unit_of(extra, None) or unit_of(unit_directive, default_unit)
    if depot == "lakeside":
        unit = "kg"
    if depot == "harbor":
        status = {"dlv": "delivered", "dll": "delivered_late", "can": "cancelled",
                  "ret": "returned", "hld": "held"}.get(status.strip().lower(), status)
    return make_record(kind, ident, when, amount * FACTORS[unit], normalize_status(status))


def parse_fixed(text):
    seq = None
    layout = None
    records = []
    for raw in text.split("\n"):
        line = raw.rstrip("\r")
        if line.startswith("\x0c") or not line.strip():
            continue
        if line.startswith("#LAYOUT"):
            layout = line.split()[1].strip()
            continue
        if line.startswith("#SEQ"):
            seq = int(line.split()[1])
            continue
        if line.startswith("#"):
            continue
        match = [name for name, spec in FW_LAYOUTS.items() if spec[0] == len(line)]
        if match:
            name = match[0]
        elif layout in FW_LAYOUTS:
            name = layout
            line = line.ljust(FW_LAYOUTS[name][0])
        else:
            continue
        length, spans, date_form, factor = FW_LAYOUTS[name]
        field = {key: line[start:end] for key, (start, end) in spans.items()}
        kind = kind_of(field["type"])
        if kind == "void":
            records.append(make_record("void", field["id"], None, None, None))
            continue
        status = {"D": "delivered", "L": "delivered_late", "C": "cancelled",
                  "R": "returned", "H": "held"}.get(field["status"].strip().upper(), "other")
        records.append(make_record(kind, field["id"], parse_time(field["shipped"], date_form),
                                   Fraction(int(field["weight"])) * factor, status))
    return seq, records


def parse_xml(data):
    root = ET.fromstring(data)
    seq = int(root.get("seq", "0"))
    root_unit = unit_of(root.get("weight-unit"), "kg")
    records = []

    def value(element, name):
        if element.get(name) is not None:
            return element.get(name)
        child = element.find(name)
        return child.text if child is not None and child.text else None

    for element in root.iter("shipment"):
        ident = element.get("id")
        kind = kind_of(element.get("type"))
        if kind == "void":
            records.append(make_record("void", ident, None, None, None))
            continue
        weight_element = element.find("weight")
        if weight_element is not None:
            text = weight_element.text
            unit = unit_of(weight_element.get("unit"), None)
        else:
            text, unit = element.get("weight"), None
        amount, suffix = split_weight(text, "dot")
        unit = unit or suffix or unit_of(element.get("weight-unit"), None) or root_unit
        records.append(make_record(kind, ident, parse_time(value(element, "shipped"), "iso"),
                                   amount * FACTORS[unit], normalize_status(value(element, "status"))))
    return seq, records


def parse_north(text):
    seq = None
    records = []
    for line in text.split("\n"):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        parsed = json.loads(line)
        objects = parsed if isinstance(parsed, list) else [parsed]
        for obj in objects:
            if not isinstance(obj, dict):
                continue
            if "meta" in obj and "id" not in obj:
                if seq is None:
                    seq = int(obj["meta"].get("seq", 0))
                continue
            kind = kind_of(obj.get("kind"))
            if kind == "void":
                records.append(make_record("void", str(obj["id"]), None, None, None))
                continue
            amount = unit = None
            for key, raw in obj.items():
                match = re.match(r"^weight_(kg|g|lb|oz)$", key.lower())
                if match:
                    amount, unit = Fraction(Decimal(str(raw))), match.group(1)
            if amount is None and "weight" in obj:
                amount, suffix = split_weight(str(obj["weight"]), "dot")
                unit = unit_of(obj.get("unit") or obj.get("weight_unit"), suffix or "kg")
            records.append(make_record(kind, str(obj["id"]), parse_time(obj["shipped_at"], "iso"),
                                       amount * FACTORS[unit], normalize_status(obj.get("status"))))
    return seq, records


def parse_file(depot, path):
    data = read_bytes(path)
    if depot == "central":
        return parse_xml(data)
    text = decode(data)
    if depot == "south":
        return parse_fixed(text)
    if depot == "north":
        return parse_north(text)
    return parse_delimited(depot, text)


def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-")[0].lower()
        exports.setdefault(depot, [])
        seq, records = parse_file(depot, path)
        exports[depot].append((seq if seq is not None else 0, name, records))

    corrections = resends = 0
    current = {}
    for depot, files in exports.items():
        state = {}
        for seq, name, records in sorted(files, key=lambda item: (item[0], item[1])):
            for record in records:
                num = record["num"]
                if record["kind"] == "new":
                    if num in state:
                        resends += 1
                    else:
                        state[num] = record
                elif record["kind"] == "correction":
                    state[num] = record
                    corrections += 1
                else:
                    state.pop(num, None)
                    corrections += 1
        current[depot] = state

    rank = {depot: index for index, depot in enumerate(PRIORITY)}
    owners = {}
    for depot, state in current.items():
        for num in state:
            owners.setdefault(num, []).append(depot)
    handovers = sum(1 for depots in owners.values() if len(depots) > 1)

    depot_totals = {depot: [0, Fraction(0)] for depot in exports}
    month_totals = {}
    for num, depots in owners.items():
        depot = min(depots, key=lambda item: rank.get(item, len(rank)))
        record = current[depot][num]
        if not counted(record["status"]):
            continue
        depot_totals[depot][0] += 1
        depot_totals[depot][1] += record["kg"]
        key = "%04d-%02d" % (record["shipped"].year, record["shipped"].month)
        entry = month_totals.setdefault(key, [0, Fraction(0)])
        entry[0] += 1
        entry[1] += record["kg"]

    def pack(entry):
        exact = Decimal(entry[1].numerator) / Decimal(entry[1].denominator) if False else None
        scaled = entry[1] * 100
        rounded = (scaled.numerator * 2 + scaled.denominator) // (scaled.denominator * 2)
        return {"shipments": entry[0], "total_kg": float(Decimal(rounded) / 100)}

    result = {
        "depots": {depot: pack(depot_totals[depot]) for depot in sorted(depot_totals)},
        "months": {key: pack(month_totals[key]) for key in sorted(month_totals)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as handle:
        json.dump(result, handle, indent=2)
        handle.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
